    let scale = 256.0 * exp2(params.mapMeta.x);
    let world = params.viewport.zw + cssPoint;
    let projectedX = (world.x / scale - 0.5) * 2.0 * INVERSE_PI * INVERSE_EARTH_RADIUS;
    let projectedY = (0.5 - world.y / scale) * 2.0 * INVERSE_PI * INVERSE_EARTH_RADIUS;
